from dataclasses import dataclass

@dataclass
class TarotCard:
    id: int
    name_ru: str
    name_en: str
    arcana: str  # 'major' or 'minor'
    suit: str | None  # 'wands', 'cups', 'swords', 'pentacles' or None
    upright_meaning: str
    reversed_meaning: str
    keywords: list[str]


